import{_ as a,o as r,c as l,a2 as i}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"تصنيف الأعراق الغريبة وتكافلها","description":"","frontmatter":{},"headers":[],"relativePath":"ar/0052-异族分类与共生.md","filePath":"ar/0052-异族分类与共生.md"}'),o={name:"ar/0052-异族分类与共生.md"};function d(e,t,n,s,h,g){return r(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="تصنيف-الأعراق-الغريبة-وتكافلها" tabindex="-1">تصنيف الأعراق الغريبة وتكافلها <a class="header-anchor" href="#تصنيف-الأعراق-الغريبة-وتكافلها" aria-label="Permalink to &quot;تصنيف الأعراق الغريبة وتكافلها&quot;">​</a></h1><table tabindex="0"><thead><tr><th>البند</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>52</td></tr><tr><td>الوحدة</td><td>الأعراق وأشكال الحياة</td></tr><tr><td>الكلمات المفتاحية</td><td>الأعراق الغريبة، معايير التصنيف، أنماط التكافل، احترام الثقافات، التكيف العرقي</td></tr></tbody></table><h2 id="أولاً-تحديد-مفهوم-الأعراق-الغريبة" tabindex="-1">أولاً: تحديد مفهوم الأعراق الغريبة <a class="header-anchor" href="#أولاً-تحديد-مفهوم-الأعراق-الغريبة" aria-label="Permalink to &quot;أولاً: تحديد مفهوم الأعراق الغريبة&quot;">​</a></h2><p>في سياق حضارة التكافل المرساة، «الأعراق الغريبة» (يي زو) مفهوم نسبي إلى العرق البشري، يشير إلى جميع الأعراق ما عدا العرق البشري. يجب التأكيد بوجه خاص على أن مفهوم «الأعراق الغريبة» له دلالة تصنيفية فقط، ولا يحمل إطلاقاً أي حكم قيمي أو معنى تمييزي. في إطار الدستور التكافلي، تتمتع الأعراق الغريبة والعرق البشري بوضع قانوني وحقوق أساسية متساوية تماماً.</p><p>الغرض من طرح مفهوم الأعراق الغريبة هو الفهم والدراسة المنهجية لأشكال الحياة المختلفة ما عدا العرق البشري، وتوفير أساس علمي لوضع سياسات تكافلية مستهدفة وإجراءات حماية ثقافية وخطط تكيف عرقي — لا اعتبار الأعراق الغريبة «آخرين» أو «غرباء».</p><h2 id="ثانياً-معايير-تصنيف-الأعراق-الغريبة" tabindex="-1">ثانياً: معايير تصنيف الأعراق الغريبة <a class="header-anchor" href="#ثانياً-معايير-تصنيف-الأعراق-الغريبة" aria-label="Permalink to &quot;ثانياً: معايير تصنيف الأعراق الغريبة&quot;">​</a></h2><p>تصنف الأعراق الغريبة في كون هنغ يوان وفق أبعاد متعددة، مشكلة نظام تصنيف متعدد الأبعاد:</p><h3 id="_1-التصنيف-حسب-نسب-الحياة" tabindex="-1">(1) التصنيف حسب نسب الحياة <a class="header-anchor" href="#_1-التصنيف-حسب-نسب-الحياة" aria-label="Permalink to &quot;(1) التصنيف حسب نسب الحياة&quot;">​</a></h3><p>هذا هو معيار التصنيف الأساسي؛ انظر <em>50-万族谱系总览</em> للتفاصيل:</p><table tabindex="0"><thead><tr><th>النسب</th><th>الأعراق الغريبة المشمولة</th></tr></thead><tbody><tr><td>الأعراق المادية الكربونية</td><td>شو زو (العرق الوحشي)، لين زو (العرق الحرشفي)، يو زو (العرق الريشي)، مو زو (العرق النباتي) وغيرها</td></tr><tr><td>الأعراق الطاقية المتكثفة</td><td>لينغ زو (العرق الروحي)، هوو زو (العرق الناري)، شوي زو (العرق المائي)، فنغ زو (العرق الريحي)، لي زو (العرق الرعدي) وغيرها</td></tr><tr><td>الأعراق الميكانيكية البناء</td><td>جي زو (العرق الآلي)، شو زو (العرق الرقمي)، جينغ زو (العرق البلوري) وغيرها</td></tr><tr><td>أعراق الوعي والمعلومة</td><td>منغ زو (العرق الحالم)، ينغ زو (العرق الظلي)، نيان زو (العرق الذهني)، هون زو (العرق الروحي) وغيرها</td></tr><tr><td>الأعراق المختلطة المتحورة</td><td>بان شو زو (العرق نصف الوحشي)، ياو لينغ زو (العرق الشيطاني الروحي)، رين جي زو (العرق البشري الآلي)، شوانغ هون تي (كيان الروحين) وغيرها</td></tr></tbody></table><h3 id="_2-التصنيف-حسب-درجة-التحضر" tabindex="-1">(2) التصنيف حسب درجة التحضر <a class="header-anchor" href="#_2-التصنيف-حسب-درجة-التحضر" aria-label="Permalink to &quot;(2) التصنيف حسب درجة التحضر&quot;">​</a></h3><table tabindex="0"><thead><tr><th>المستوى</th><th>الاسم</th><th>الخصائص</th><th>الأعراق الممثلة</th></tr></thead><tbody><tr><td>المستوى الأول</td><td>أعراق الحضارة البدائية</td><td>لم تنشئ بعد مؤسسات اجتماعية مستقرة، تعيش بشكل قبلي</td><td>بعض فروع شو زو، مو زو البدائية</td></tr><tr><td>المستوى الثاني</td><td>أعراق الحضارة الكلاسيكية</td><td>أنشأت مؤسسات دولة وثقافة كلاسيكية، في مرحلة الزراعة أو الحرف اليدوية</td><td>بعض لين زو، يو زو</td></tr><tr><td>المستوى الثالث</td><td>أعراق الحضارة التكنولوجية</td><td>طورت حضارة تكنولوجية، دخلت العصر الصناعي أو المعلوماتي</td><td>جي زو، شو زو، بعض رين زو</td></tr><tr><td>المستوى الرابع</td><td>أعراق الحضارة الزراعية</td><td>تتخذ نظام الزراعة شكلاً حضارياً أساسياً، والمزارعون يهيمنون على المجتمع</td><td>لينغ زو، لونغ زو، بعض رين زو</td></tr><tr><td>المستوى الخامس</td><td>أعراق الحضارة التكافلية</td><td>انضمت إلى حضارة التكافل المرساة وقبلت مفاهيمها ومؤسساتها</td><td>جميع الأعراق المنضمة إلى الحضارة التكافلية</td></tr></tbody></table><h3 id="_3-التصنيف-حسب-التكيف-البيئي" tabindex="-1">(3) التصنيف حسب التكيف البيئي <a class="header-anchor" href="#_3-التصنيف-حسب-التكيف-البيئي" aria-label="Permalink to &quot;(3) التصنيف حسب التكيف البيئي&quot;">​</a></h3><ul><li><strong>أعراق برية</strong>: أعراق متكيفة مع البيئات البرية، كرين زو وشو زو وجي زو.</li><li><strong>أعراق مائية</strong>: أعراق متكيفة مع البيئات المائية، كلين زو وشوي زو وبعض الأعراق المختلطة.</li><li><strong>أعراق جوية</strong>: أعراق متكيفة مع البيئات المرتفعة أو الطيران، كيو زو وفنغ زو.</li><li><strong>أعراق نارية</strong>: أعراق متكيفة مع البيئات شديدة الحرارة، كهوو زو وبعض لين زو.</li><li><strong>أعراق جليدية</strong>: أعراق متكيفة مع البيئات شديدة البرودة، كبينغ زو وبعض مو زو.</li><li><strong>أعراق طاقية</strong>: أعراق متكيفة مع بيئات الطاقة عالية التركيز، كلينغ زو ولي زو.</li><li><strong>أعراق مكانية</strong>: أعراق متكيفة مع شقوق الفضاء أو بيئات الفضاء الغريب، كينغ زو وبعض نيان زو.</li></ul><h3 id="_4-التصنيف-حسب-الشكل-الاجتماعي" tabindex="-1">(4) التصنيف حسب الشكل الاجتماعي <a class="header-anchor" href="#_4-التصنيف-حسب-الشكل-الاجتماعي" aria-label="Permalink to &quot;(4) التصنيف حسب الشكل الاجتماعي&quot;">​</a></h3><ul><li><strong>أعراق فردانية</strong>: تؤكد الاستقلال والحرية الفردية، ببنى اجتماعية مفككة، كبعض لينغ زو وينغ زو.</li><li><strong>أعراق جماعية</strong>: تؤكد المصلحة الجماعية والتعاون، ببنى اجتماعية متماسكة، كيي زو (العرق النملي)، فنغ زو (العرق النحلي) وبعض جي زو.</li><li><strong>أعراق عائلية</strong>: تتخذ الأسرة الدموية وحدة اجتماعية أساسية، كلونغ زو وبعض شو زو.</li><li><strong>أعراق دينية</strong>: تتخذ العقيدة الدينية نواة للتماسك الاجتماعي، كبعض الأعراق الطقسية.</li><li><strong>أعراق تقنية</strong>: تتخذ التطور التقني هدفاً اجتماعياً أساسياً، كجي زو وشو زو.</li></ul><h2 id="ثالثاً-أنماط-التكافل-الرئيسية-للأعراق-الغريبة" tabindex="-1">ثالثاً: أنماط التكافل الرئيسية للأعراق الغريبة <a class="header-anchor" href="#ثالثاً-أنماط-التكافل-الرئيسية-للأعراق-الغريبة" aria-label="Permalink to &quot;ثالثاً: أنماط التكافل الرئيسية للأعراق الغريبة&quot;">​</a></h2><p>تتخذ حضارة التكافل المرساة أنماط تكافل مختلفة لأنواع مختلفة من الأعراق الغريبة:</p><h3 id="_1-أنماط-تكافل-الأعراق-المادية-الكربونية" tabindex="-1">(1) أنماط تكافل الأعراق المادية الكربونية <a class="header-anchor" href="#_1-أنماط-تكافل-الأعراق-المادية-الكربونية" aria-label="Permalink to &quot;(1) أنماط تكافل الأعراق المادية الكربونية&quot;">​</a></h3><ul><li><strong>شو زو (العرق الوحشي)</strong>: استثمار مزايا العرق الوحشي البدنية والحسية في أداء أدوار مهمة في استكشاف الموارد وحماية الأمن ومراقبة البيئة. وحماية الثقافة القبلية والتقاليد البرية للعرق الوحشي، ومنع الاستئناس القسري.</li><li><strong>لين زو (العرق الحرشفي)</strong>: استثمار قدرة العرق الحرشفي على التكيف المائي في أداء أدوار في تنمية الموارد المائية والبناء تحت الماء وحماية البيئة المائية. وباعتباره فرعاً قوياً من العرق الحرشفي، يلعب لونغ زو (العرق التنيني) دوراً مهماً في الزراعة العليا وحماية الحضارة.</li><li><strong>يو زو (العرق الريشي)</strong>: استثمار قدرة العرق الريشي على الطيران في أداء أدوار في النقل الجوي ومراقبة الطقس ودوريات الأجواء. وحماية موائل العرق الريشي المرتفعة ومسارات هجرته.</li><li><strong>مو زو (العرق النباتي)</strong>: استثمار قدرة العرق النباتي على التكافل الطبيعي في أداء أدوار في حماية البيئة ومعالجة البيئة وتنمية الموارد النباتية والطب العلاجي. عمره الطويل يجعله قوة مهمة في نقل التاريخ والتخطيط طويل المدى.</li></ul><h3 id="_2-أنماط-تكافل-الأعراق-الطاقية-المتكثفة" tabindex="-1">(2) أنماط تكافل الأعراق الطاقية المتكثفة <a class="header-anchor" href="#_2-أنماط-تكافل-الأعراق-الطاقية-المتكثفة" aria-label="Permalink to &quot;(2) أنماط تكافل الأعراق الطاقية المتكثفة&quot;">​</a></h3><ul><li><strong>لينغ زو (العرق الروحي)</strong>: استثمار قدرة العرق الروحي على التحكم بالطاقة وموهبته في الزراعة في أداء أدوار أساسية في بحث أنظمة الزراعة وضبط الطاقة وتوجيه الزراعة العليا. العرق الروحي باحث ووريث مهم لثلاثمائة نظام زراعة أصلي.</li><li><strong>الأعراق العنصرية (هوو/شوي/فنغ/لي)</strong>: استثمار قدرات التحكم بالعناصر لكل عرق في أداء أدوار في تنمية الطاقة ومعالجة البيئة والإنتاج الصناعي والوقاية من الكوارث. ووضع أنظمة إدارة أمان الطاقة العنصرية لمنع الضرر الناجم عن فقدان السيطرة على الطاقة.</li></ul><h3 id="_3-أنماط-تكافل-الأعراق-الميكانيكية-البناء" tabindex="-1">(3) أنماط تكافل الأعراق الميكانيكية البناء <a class="header-anchor" href="#_3-أنماط-تكافل-الأعراق-الميكانيكية-البناء" aria-label="Permalink to &quot;(3) أنماط تكافل الأعراق الميكانيكية البناء&quot;">​</a></h3><ul><li><strong>جي زو (العرق الآلي)</strong>: استثمار قدرة الحساب والدفاع البدني للعرق الآلي في أداء أدوار أساسية في بناء البنى التحتية والإنتاج الصناعي والحماية الأمنية واستكشاف الفضاء العميق. العرق الآلي باني مهم لعتاد المرساة وبنيتها التحتية.</li><li><strong>شو زو (العرق الرقمي)</strong>: استثمار قدرات معالجة البيانات والتحكم بالمعلومة للعرق الرقمي في أداء أدوار أساسية في البناء المعلوماتي وتحليل البيانات وأمن الشبكات والذكاء الاصطناعي. العرق الرقمي صائن مهم لتقنية الاتصال عبر الأبعاد والشبكة التكافلية.</li><li><strong>جينغ زو (العرق البلوري)</strong>: استثمار قدرة العرق البلوري على تخزين وتحويل الطاقة في أداء أدوار في احتياط الطاقة وتوحيد مقاييس الطاقة ونقل الطاقة.</li></ul><h3 id="_4-أنماط-تكافل-أعراق-الوعي-والمعلومة" tabindex="-1">(4) أنماط تكافل أعراق الوعي والمعلومة <a class="header-anchor" href="#_4-أنماط-تكافل-أعراق-الوعي-والمعلومة" aria-label="Permalink to &quot;(4) أنماط تكافل أعراق الوعي والمعلومة&quot;">​</a></h3><ul><li><strong>منغ زو (العرق الحالم)</strong>: استثمار قدرة العرق الحالم على التواصل الوعي في أداء أدوار في العلاج النفسي وبحوث الوعي والتواصل بين الأعراق والتبادل الثقافي. ووضع أنظمة إدارة فضاء الأحلام لمنع الاقتحام الوعي وانتهاك الخصوصية.</li><li><strong>ينغ زو (العرق الظلي)</strong>: استثمار قدرتي التخفي والتسلل للعرق الظلي في أداء أدوار في الاستطلاع الأمني وجمع المعلومات والمهام الخاصة. ووضع قواعد سلوك للعرق الظلي لمنع استخدام قدرة الإخفاء في أنشطة غير قانونية.</li><li><strong>نيان زو (العرق الذهني)</strong>: استثمار القوة العقلية وقدرة التحكم الذهني للعرق الذهني في أداء أدوار في بحث تطور الوعي والعلاج العقلي وتوجيه الزراعة العليا. ووضع قواعد استخدام القوة العقلية لمنع التحكم العقلي والتلاعب بالوعي.</li></ul><h3 id="_5-أنماط-تكافل-الأعراق-المختلطة-المتحورة" tabindex="-1">(5) أنماط تكافل الأعراق المختلطة المتحورة <a class="header-anchor" href="#_5-أنماط-تكافل-الأعراق-المختلطة-المتحورة" aria-label="Permalink to &quot;(5) أنماط تكافل الأعراق المختلطة المتحورة&quot;">​</a></h3><p>بسبب أشكال حياتها الخاصة، تحتاج الأعراق المختلطة المتحورة إلى سياسات تكافل أكثر دقة:</p><ul><li>وضع نظام تسجيل وتوثيق هوية للأعراق المختلطة المتحورة لتأكيد وضعها القانوني.</li><li>توفير خدمات عامة مناسبة (طبية وتعليمية وسكنية وغيرها) لمختلف الأشكال المختلطة.</li><li>معارضة التمييز والإقصاء ضد الأعراق المختلطة المتحورة وتعزيز القبول الاجتماعي.</li><li>بالنسبة للأشكال المختلطة الخاصة كشوانغ هون تي (كيان الروحين)، تطبيق <em>58-双魂伦理准则</em> للإدارة المتخصصة.</li></ul><h2 id="رابعاً-حماية-ثقافات-الأعراق-الغريبة" tabindex="-1">رابعاً: حماية ثقافات الأعراق الغريبة <a class="header-anchor" href="#رابعاً-حماية-ثقافات-الأعراق-الغريبة" aria-label="Permalink to &quot;رابعاً: حماية ثقافات الأعراق الغريبة&quot;">​</a></h2><p>ثقافات الأعراق الغريبة جزء مهم من التنوع الثقافي لعشرة آلاف عرق. تتخذ الدولة الإجراءات التالية لحماية ثقافات الأعراق الغريبة:</p><ol><li><strong>المسح والتوثيق الثقافي</strong>: إجراء مسوح وتوثيق منهجي لثقافة كل عرق، وإنشاء أرشيف لثقافات عشرة آلاف عرق، ومنع ضياع الثقافات.</li><li><strong>حماية اللغات والكتابات</strong>: حماية لغات وكتابات كل عرق، ودعم تعليم واستخدام لغات وكتابات الأعراق الغريبة، وإنشاء نظام خدمات عامة متعدد اللغات.</li><li><strong>حماية الأعياد التقليدية</strong>: احترام الأعياد التقليدية والأعراف لكل عرق، ومراعاة الأعياد المهمة لكل عرق في ترتيب العطلات العامة.</li><li><strong>دعم نقل الثقافة</strong>: دعم تدريب ورثة الثقافة لكل عرق وتنظيم الأنشطة الثقافية، مع توفير الدعم المالي والمكاني.</li><li><strong>تعزيز التبادل الثقافي</strong>: تنظيم مهرجانات ثقافية لعشرة آلاف عرق ومعارض ثقافية وأنشطة أخرى بانتظام لتعزيز التبادل الثقافي والاستفادة المتبادلة بين جميع الأعراق.</li><li><strong>حماية الملكية الفكرية الثقافية</strong>: حماية الملكية الفكرية للثقافات التقليدية لكل عرق، ومنع النهب الثقافي والتسويق غير اللائق.</li></ol><h2 id="خامساً-إدارة-شؤون-الأعراق-الغريبة" tabindex="-1">خامساً: إدارة شؤون الأعراق الغريبة <a class="header-anchor" href="#خامساً-إدارة-شؤون-الأعراق-الغريبة" aria-label="Permalink to &quot;خامساً: إدارة شؤون الأعراق الغريبة&quot;">​</a></h2><p>تقيم الدولة وزارة الشؤون العرقية، المكلفة تحديداً بإدارة وتنسيق شؤون الأعراق الغريبة:</p><ul><li><strong>نظام الممثلين العرقيين</strong>: تزويد مؤسسات الحكم على جميع المستويات بممثلين عن الأعراق الغريبة بنسبة تمثيلية لضمان حقها في الكلام.</li><li><strong>سياسات التكيف العرقي</strong>: وضع سياسات خدمات عامة مختلفة حسب الخصائص الفسيولوجية والاحتياجات الثقافية للأعراق المختلفة.</li><li><strong>وساطة النزاعات العرقية</strong>: إنشاء آلية وساطة للنزاعات العرقية لحل التناقضات والصراعات العرقية في الوقت المناسب.</li><li><strong>المساعدة القانونية للأعراق الغريبة</strong>: تقديم مساعدة قانونية للأعراق الغريبة لضمان معاملتها بالمساواة في الإجراءات القضائية.</li><li><strong>دعم تنمية الأعراق الغريبة</strong>: تقديم دعم خاص للأعراق المتأخرة نسبياً في التنمية لمساعدتها على رفع مستوى تحضرها ومعيشتها.</li></ul><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p>الأعراق الغريبة ليست «الآخرين» للعرق البشري، بل أعضاء متساوون في أسرة تكافل عشرة آلاف عرق الكبرى. من خلال إنشاء نظام تصنيف متعدد الأبعاد، واعتماد أنماط تكافل مختلفة، وحماية ثقافات الأعراق الغريبة، وتحسين إدارة شؤونها، تضمن حضارة التكافل المرساة أن كل عرق غريب يجد مكانه المناسب في نظام التكافل، ويستثمر مزاياها الفريدة، ويتطور ويزدهر مع الأعراق الأخرى.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>50-万族谱系总览 (نظرة عامة على أنساب عشرة آلاف عرق)</li><li>51-人族定位与特质 (تحديد موقع العرق البشري وخصائصه)</li><li>53-奇特生命识别标准 (معايير التعرف على الحياة الشاذة)</li><li>05-万族共进基本纲领 (البرنامج الأساسي لتقدم عشرة آلاف عرق معاً)</li></ul>',39)])])}const _=a(o,[["render",d]]);export{b as __pageData,_ as default};
